"""Deepgram ASR engine implementation.

Version-specific logic (query-parameter building, event parsing, keep-alive
semantics) is encapsulated in private handler classes ``_DeepgramV1`` and
``_DeepgramV2``. ``DeepgramASR`` selects and holds the active handler at
construction time, eliminating any version-branching inside the engine.
"""

import json
import os
from abc import ABC, abstractmethod
from typing import Any, List, Optional, cast
from urllib.parse import urlencode

import structlog
import websockets
import websockets.exceptions
from websockets.legacy.client import WebSocketClientProtocol

from rasa.core.channels.voice_stream.asr.asr_engine import (
    ASREngine,
    ASRLanguageMapEntry,
)
from rasa.core.channels.voice_stream.asr.asr_event import (
    ASREvent,
    NewTranscript,
    UserIsSpeaking,
)
from rasa.core.channels.voice_stream.asr.deepgram.config import (
    DEEPGRAM_CONFIG_ADAPTER,
    DeepgramASRConfig,
    DeepgramV1ASRConfig,
    DeepgramV2ASRConfig,
)
from rasa.core.channels.voice_stream.asr.deepgram.constants import (
    DEEPGRAM_API_V1,
    DEEPGRAM_API_V2,
    DEFAULT_ENDPOINT,
    DEFAULT_V1_ENDPOINTING,
    DEFAULT_V1_MODEL,
    DEFAULT_V1_SMART_FORMAT,
    DEFAULT_V1_UTTERANCE_END_MS,
    DEFAULT_V2_MODEL,
)
from rasa.core.channels.voice_stream.audio_bytes import (
    L16_24KHZ,
    L16_48KHZ,
    MULAW_8KHZ,
    AudioFormat,
    CurrentLanguageConfig,
    RasaAudioBytes,
)
from rasa.shared.constants import DEEPGRAM_API_KEY_ENV_VAR

logger = structlog.get_logger(__name__)


def _extract_deepgram_v1_transcript(data: dict[str, Any]) -> Optional[str]:
    """Return the first transcript from a v1 ``Results`` frame, if present."""
    channel = data.get("channel")
    if not isinstance(channel, dict):
        return None

    alternatives = channel.get("alternatives")
    if not isinstance(alternatives, list) or not alternatives:
        return None

    first_alternative = alternatives[0]
    if not isinstance(first_alternative, dict):
        return None

    transcript = first_alternative.get("transcript")
    if not transcript:
        return None

    return str(transcript)


# ======================================================================================
# Version-specific handlers
# ======================================================================================


class _DeepgramVersionHandler(ABC):
    """Common interface for v1 / v2 API-specific logic.

    Each concrete subclass encapsulates everything that differs between the
    ``/v1/listen`` (Nova) and ``/v2/listen`` (Flux) endpoints: query-parameter
    construction, websocket-event parsing, and keep-alive semantics.
    ``DeepgramASR`` delegates all version-specific calls to the active handler.
    """

    @property
    @abstractmethod
    def api_version(self) -> str:
        """Version string used in the websocket URL path (``v1`` or ``v2``)."""

    @abstractmethod
    def build_query_params(
        self,
        audio_format: AudioFormat,
        language_config: CurrentLanguageConfig,
    ) -> str:
        """Return a URL-encoded query string for the websocket connection."""

    @abstractmethod
    def parse_event(self, message: Any) -> Optional[ASREvent]:
        """Translate one raw websocket message into a Rasa ``ASREvent``."""

    @abstractmethod
    async def send_keep_alive(self, socket: Optional[WebSocketClientProtocol]) -> None:
        """Send a keep-alive heartbeat if the API supports it."""

    @staticmethod
    def _encoding_for(audio_format: AudioFormat) -> str:
        """Return the Deepgram encoding string for *audio_format*.

        Raises:
            ValueError: When the audio format is not supported.
        """
        if audio_format in (L16_24KHZ, L16_48KHZ):
            return "linear16"
        if audio_format == MULAW_8KHZ:
            return "mulaw"
        raise ValueError(f"Unsupported audio format: {audio_format}")


class _DeepgramV1(_DeepgramVersionHandler):
    """Handler for the Deepgram ``/v1/listen`` (Nova) API.

    Accumulates ``Results`` fragments into a complete utterance and emits
    ``NewTranscript`` on ``speech_final`` or ``UtteranceEnd``.
    """

    @property
    def api_version(self) -> str:
        return DEEPGRAM_API_V1

    def __init__(self, config: DeepgramV1ASRConfig) -> None:
        self._config = config
        # Bridges multiple ``Results`` events into one complete utterance
        # before a ``NewTranscript`` is emitted.
        self._accumulated_transcript: str = ""

    def build_query_params(
        self,
        audio_format: AudioFormat,
        language_config: CurrentLanguageConfig,
    ) -> str:
        """Build URL-encoded query params for the ``/v1/listen`` endpoint."""
        params: dict = {
            "encoding": self._encoding_for(audio_format),
            "sample_rate": audio_format.sample_rate,
            "endpointing": self._config.endpointing,
            "vad_events": "true",
            "language": language_config.engine_language_key,
            "interim_results": "true",
            "model": language_config.model,
            "smart_format": str(self._config.smart_format).lower(),
        }
        if self._config.utterance_end_ms and self._config.utterance_end_ms > 0:
            params["utterance_end_ms"] = self._config.utterance_end_ms
        return urlencode(params)

    def parse_event(self, message: Any) -> Optional[ASREvent]:
        """Translate one ``/v1/listen`` websocket frame into a Rasa ``ASREvent``."""
        data = json.loads(message) if isinstance(message, (str, bytes)) else message
        data_type = data.get("type")

        if data_type == "Results":
            transcript = _extract_deepgram_v1_transcript(data)

            if data.get("is_final"):
                transcript_text = transcript or ""
                if data.get("speech_final"):
                    # End of a speech segment — flush the accumulator and emit.
                    full = (
                        self._accumulated_transcript.strip()
                        + " "
                        + transcript_text.strip()
                    ).strip()
                    # Reset for the next turn.
                    self._accumulated_transcript = ""
                    if full:
                        return NewTranscript(full)
                else:
                    # Intermediate final result — append and wait for speech_final.
                    self._accumulated_transcript = (
                        self._accumulated_transcript.strip()
                        + " "
                        + transcript_text.strip()
                    ).strip()
            elif transcript:
                # Non-final (interim) result — signal that the user is speaking.
                return UserIsSpeaking(transcript)

        elif data_type == "UtteranceEnd":
            # Fallback flush: Deepgram detected a long silence but speech_final
            # never arrived — emit whatever was accumulated so far.
            if self._accumulated_transcript:
                transcript = self._accumulated_transcript
                # Reset for the next turn.
                self._accumulated_transcript = ""
                return NewTranscript(transcript)

        return None

    async def send_keep_alive(self, socket: Optional[WebSocketClientProtocol]) -> None:
        """Send a ``KeepAlive`` frame to the v1 websocket."""
        if socket is None or not socket.open:
            return
        await socket.send(json.dumps({"type": "KeepAlive"}))


class _DeepgramV2(_DeepgramVersionHandler):
    """Handler for the Deepgram ``/v2/listen`` (Flux) API.

    Signals speech onset on ``StartOfTurn``, tracks the latest ``Update``
    transcript, and commits it on ``EndOfTurn``. The v2 endpoint rejects
    ``KeepAlive`` messages, so :meth:`send_keep_alive` is a no-op.
    """

    @property
    def api_version(self) -> str:
        return DEEPGRAM_API_V2

    def __init__(self, config: DeepgramV2ASRConfig) -> None:
        self._config = config
        # v2 Update events carry the full current-turn transcript; only the
        # latest value is needed for the subsequent EndOfTurn commit.
        self._accumulated_transcript: str = ""

    def build_query_params(
        self,
        audio_format: AudioFormat,
        language_config: CurrentLanguageConfig,
    ) -> str:
        """Build URL-encoded query params for the ``/v2/listen`` endpoint."""
        params: dict = {
            "encoding": self._encoding_for(audio_format),
            "sample_rate": audio_format.sample_rate,
            "model": language_config.model,
        }
        if language_config.engine_language_key:
            params["language_hint"] = language_config.engine_language_key
        if self._config.eot_threshold is not None:
            params["eot_threshold"] = self._config.eot_threshold
        if self._config.eot_timeout_ms is not None:
            params["eot_timeout_ms"] = self._config.eot_timeout_ms
        return urlencode(params)

    def parse_event(self, message: Any) -> Optional[ASREvent]:
        """Translate one ``/v2/listen`` websocket frame into a Rasa ``ASREvent``."""
        data = message if isinstance(message, dict) else json.loads(message)
        data_type = data.get("type")

        if data_type == "Connected":
            logger.info("deepgram.v2.connected", request_id=data.get("request_id"))
            return None

        if data_type == "Error":
            logger.error(
                "deepgram.v2.error",
                error_message=data.get("message"),
                error_code=data.get("code"),
            )
            return None

        if data_type != "TurnInfo":
            return None

        event_type = data.get("event")
        transcript = data.get("transcript", "")

        if event_type == "StartOfTurn":
            self._accumulated_transcript = ""
            return UserIsSpeaking(text="")

        if event_type == "Update":
            # v2 sends the full current-turn transcript on every Update; replace.
            if not transcript:
                return None
            self._accumulated_transcript = transcript
            return UserIsSpeaking(text=transcript)

        if event_type == "EndOfTurn":
            if self._accumulated_transcript:
                committed = self._accumulated_transcript
                self._accumulated_transcript = ""
                return NewTranscript(text=committed)
            return None

        return None

    async def send_keep_alive(self, socket: Optional[WebSocketClientProtocol]) -> None:
        """No-op: v2 rejects ``KeepAlive`` with ``UNPARSABLE_CLIENT_MESSAGE``."""
        return None


# ======================================================================================
# Public engine
# ======================================================================================


class DeepgramASR(ASREngine[DeepgramASRConfig]):
    """Deepgram STT engine supporting both Nova (v1) and Flux (v2).

    The active API variant is resolved at construction time via the
    discriminated union in :mod:`.config`. Version-specific logic
    is fully encapsulated in :class:`_DeepgramV1` / :class:`_DeepgramV2`;
    the engine itself has no version-branching.
    """

    required_env_vars = (DEEPGRAM_API_KEY_ENV_VAR,)

    @classmethod
    def name(cls) -> str:
        return "deepgram"

    def __init__(
        self,
        rasa_language: str,
        format: AudioFormat,
        config: Optional[DeepgramASRConfig] = None,
        additional_languages: Optional[List[str]] = None,
    ):
        # Config resolution (v1/v2 selection) happens in the overridden _resolve_config
        # hook.
        super().__init__(rasa_language, format, config, additional_languages)
        self._handler: _DeepgramVersionHandler = self._create_handler()

    def _create_handler(self) -> _DeepgramVersionHandler:
        """Instantiate the version-specific handler from the resolved config."""
        if isinstance(self.config, DeepgramV2ASRConfig):
            return _DeepgramV2(self.config)
        return _DeepgramV1(self.config)

    async def open_websocket_connection(self) -> WebSocketClientProtocol:
        """Connect to the Deepgram websocket."""
        deepgram_api_key = os.environ[DEEPGRAM_API_KEY_ENV_VAR]
        extra_headers = {"Authorization": f"Token {deepgram_api_key}"}
        url = self._get_api_url() + self._get_query_params()
        try:
            return await websockets.connect(  # type: ignore
                url,
                extra_headers=extra_headers,
            )
        except websockets.exceptions.InvalidStatusCode as e:
            if e.status_code == 401:
                error_msg = "Please make sure your Deepgram API key is correct."
            else:
                error_msg = "Connection to Deepgram failed."
            logger.error(
                "deepgram.connection.failed",
                status_code=e.status_code,
                error=error_msg,
                url=url,
            )
            raise

    def _get_api_url(self) -> str:
        """Build the base websocket URL for the active API version."""
        return f"wss://{self.config.endpoint}/{self._handler.api_version}/listen?"

    def _get_query_params(self) -> str:
        """Return URL-encoded query params for the active API version."""
        return self._handler.build_query_params(
            self.audio_format, self.current_language_config
        )

    async def signal_audio_done(self) -> None:
        """Signal to Deepgram that no more audio will be sent."""
        if self.asr_socket is None:
            raise AttributeError("Websocket not connected.")
        await self.asr_socket.send(json.dumps({"type": "CloseStream"}))

    def rasa_audio_bytes_to_engine_bytes(self, chunk: RasaAudioBytes) -> bytes:
        """Convert ``RasaAudioBytes`` to raw bytes for the Deepgram stream."""
        return chunk.data

    def engine_event_to_asr_event(self, e: Any) -> Optional[ASREvent]:
        """Translate a raw Deepgram event into a Rasa ``ASREvent``."""
        return self._handler.parse_event(e)

    async def send_keep_alive(self) -> None:
        """Forward a keep-alive heartbeat to the active handler."""
        await self._handler.send_keep_alive(self.asr_socket)

    # ---- Config plumbing -------------------------------------------------------

    def _resolve_config(
        self,
        config: Optional[DeepgramASRConfig],
        rasa_language: str,
    ) -> DeepgramASRConfig:
        """Build the final config from the caller-supplied value and defaults.

        Overrides the base hook to select between the two Deepgram variants:
        v2 configs are merged onto the v2 default; v1 configs (and ``None``)
        are merged onto the v1 default.
        """
        if isinstance(config, DeepgramV2ASRConfig):
            return cast(
                DeepgramASRConfig,
                self.get_default_v2_config(rasa_language)
                .merge(config)
                .apply_deprecated_fields(rasa_language),
            )
        return cast(
            DeepgramASRConfig,
            self.get_default_config(rasa_language)
            .merge(config)
            .apply_deprecated_fields(rasa_language),
        )

    @staticmethod
    def get_default_config(rasa_language: str) -> DeepgramV1ASRConfig:
        """Return the default v1 config."""
        return DeepgramV1ASRConfig(
            endpoint=DEFAULT_ENDPOINT,
            endpointing=DEFAULT_V1_ENDPOINTING,
            smart_format=DEFAULT_V1_SMART_FORMAT,
            utterance_end_ms=DEFAULT_V1_UTTERANCE_END_MS,
            language_map={
                rasa_language: ASRLanguageMapEntry(
                    language="en",
                    model=DEFAULT_V1_MODEL,
                ),
            },
        )

    @staticmethod
    def get_default_v2_config(rasa_language: str) -> DeepgramV2ASRConfig:
        """Return the default v2 config."""
        return DeepgramV2ASRConfig(
            endpoint=DEFAULT_ENDPOINT,
            language_map={
                rasa_language: ASRLanguageMapEntry(
                    model=DEFAULT_V2_MODEL,
                ),
            },
        )

    @classmethod
    def from_config_dict(
        cls,
        config: Any,
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> "DeepgramASR":
        """Create a ``DeepgramASR`` instance from a raw config dictionary.

        Runs the discriminated-union validator so the returned engine carries
        either a :class:`~config.DeepgramV1ASRConfig` or a
        :class:`~config.DeepgramV2ASRConfig`.
        """
        parsed = DEEPGRAM_CONFIG_ADAPTER.validate_python(config or {})
        return cls(
            rasa_language=rasa_language,
            format=format,
            config=parsed,
            additional_languages=additional_languages,
        )
